<template><section class="reenroll"><button type="button" @click="open">Send re-enrollment package</button><form v-if="opened" @submit.stop.prevent="send"><h4>Re-enroll using the existing client record</h4><p>Send the current documents to an authorized portal contact. This retains the previous provider history and does not reactivate services or schedule appointments.</p><p v-if="loading" role="status">Loading current documents and portal contacts…</p><p v-if="error" role="alert">{{error}}</p><template v-if="options&&!loading"><label>Past service<select v-model="selectedService" required><option value="">Choose past service</option><option v-for="s in options.services" :key="s.id" :value="s.id">{{s.label}} · {{s.providerName}}</option></select></label><label>Authorized portal contact<select v-model="recipientId" required><option value="">Choose contact</option><option v-for="c in options.contacts" :key="c.id" :value="c.id">{{c.name}} · {{c.email}}</option></select></label><p>{{options.confirmation}}</p><ul><li v-for="d in options.documents" :key="d.id">{{d.title}}</li></ul><label><input type="checkbox" v-model="confirmed" /> I reviewed this client, recipient, and current package.</label><button v-if="!result" type="submit" :disabled="busy||!confirmed||!recipientId||!selectedService">{{busy?'Sending…':'Send secure package invitation'}}</button><p v-if="result" role="status">{{result.deliveryStatus==='sent'?'Package invitation sent.':result.alreadyCreated?'Package already recorded. Check its delivery before sending again.':'Package recorded. Check delivery before sending again.'}}</p></template><button type="button" :disabled="busy" @click="opened=false">Close</button></form></section></template>
<script setup>
import {ref,watch,onUnmounted} from 'vue';
import api from '../../services/api';
const props=defineProps({clientId:{type:[Number,String],required:true},agencyId:{type:[Number,String],required:true},serviceId:[Number,String]});
const opened=ref(false),loading=ref(false),busy=ref(false),options=ref(null),selectedService=ref(''),recipientId=ref(''),confirmed=ref(false),error=ref(''),result=ref(null);let generation=0,key='';
async function open(){const own=++generation;opened.value=true;loading.value=true;options.value=null;error.value='';result.value=null;confirmed.value=false;recipientId.value='';selectedService.value=props.serviceId||'';key=crypto.randomUUID();try{const {data}=await api.get(`/clients/${props.clientId}/reenrollment/options`,{params:{agencyId:props.agencyId}});if(own===generation){options.value=data;if(data.contacts.length===1)recipientId.value=data.contacts[0].id;}}catch(e){if(own===generation)error.value=e.response?.data?.error?.message||'This package could not be prepared.';}finally{if(own===generation)loading.value=false;}}
async function send(){if(busy.value||!confirmed.value)return;const own=generation;busy.value=true;error.value='';try{const {data}=await api.post(`/clients/${props.clientId}/reenrollment`,{agencyId:Number(props.agencyId),serviceId:Number(selectedService.value),recipientUserId:Number(recipientId.value),confirmed:true,requestKey:key});if(own===generation)result.value=data;}catch(e){if(own===generation)error.value=e.response?.data?.error?.message||'Sending could not be confirmed. Retry safely using this same request.';}finally{if(own===generation)busy.value=false;}}
watch(()=>[props.clientId,props.agencyId,props.serviceId],()=>{generation++;opened.value=false;options.value=null;error.value='';busy.value=false;});onUnmounted(()=>{generation++;});
</script>
<style scoped>.reenroll form{display:grid!important;gap:12px;padding:16px;border:1px solid #c5d8df;border-radius:10px}.reenroll label{display:grid;gap:6px}.reenroll button{font:inherit;min-height:40px;margin:4px 0;padding:8px;border:1px solid #9ab4bf;border-radius:7px;background:white;cursor:pointer}</style>
